-- Alternative: each component normalized to 0-100, then averaged
SELECT 
    ROUND(CAST(AVG(
        (c.report_compliance + c.stakeholder_satisf * 20.0 + c.dataqualityvalue * 20.0) / 3.0
    ) AS numeric), 2) AS test1,
    ROUND(CAST(AVG(
        c.report_compliance + c.stakeholder_satisf * 20.0 + c.dataqualityvalue * 20.0
    ) / 300.0 * 100) AS numeric), 2) AS test2
FROM coordinationandevaluation c;

-- Normalize each to 0-1, average, then scale to 0-100
SELECT 
    ROUND(CAST(AVG(
        (c.report_compliance / 100.0 + c.stakeholder_satisf / 5.0 + c.dataqualityvalue / 5.0) / 3.0 * 100
    ) AS numeric), 2) AS norm_cqi
FROM coordinationandevaluation c;

-- Check relationship: coordinationandevaluation -> operations -> disasterevents
